// Mission 1: interactive constraint-satisfaction puzzle.
const fuseData=[{id:'красный',label:'Красный',className:'red',icon:'⚡'},{id:'синий',label:'Синий',className:'blue',icon:'✦'},{id:'жёлтый',label:'Жёлтый',className:'yellow',icon:'☀'}];
const circuitData=[{id:'Аудитория',label:'СВЕТ',title:'Аудитория',icon:'☼',allow:['красный','жёлтый']},{id:'Техническая',label:'СИСТЕМА',title:'Серверная',icon:'⌘',allow:['красный','синий']},{id:'Выход',label:'ДВЕРЬ',title:'Выход',icon:'↗',allow:['синий','жёлтый']}];
let fuseState={},selectedFuse=null,missionComplete=false;
function cspCompletion(current){const taken=Object.values(current).filter(Boolean);if(new Set(taken).size!==taken.length)return null;for(const circuit of circuitData){if(current[circuit.id]&&!circuit.allow.includes(current[circuit.id]))return null}function search(i,assigned,used){if(i===circuitData.length)return {...assigned};const circuit=circuitData[i];if(assigned[circuit.id])return search(i+1,assigned,used);for(const f of circuit.allow){if(!used.has(f)){assigned[circuit.id]=f;used.add(f);const result=search(i+1,assigned,used);if(result)return result;used.delete(f);delete assigned[circuit.id]}}return null}return search(0,{...current},new Set(taken))}
show1=function(){chapter=1;fuseState={};selectedFuse=null;missionComplete=false;frame(1,'Последняя пара','QAIRU','','',`<div class="mission-game"><span class="mission-eyebrow">МИНИ-ИГРА 01 &nbsp; / &nbsp; QAIRU</span><h2>Верни свет. Открой дверь.</h2><p class="mission-intro">После сбоя все застряли в университете. Подключи три предохранителя — и помоги QairuBot восстановить питание.</p><div class="mission-how"><span class="how-num">1</span> Выбери предохранитель <span class="how-arrow">→</span> <span class="how-num">2</span> Нажми на подходящий разъём</div><div class="mission-board"><div class="board-head"><div><span class="board-overline">ЭЛЕКТРОЩИТОК · QAIRU</span><strong>ВОССТАНОВЛЕНИЕ СИСТЕМЫ</strong></div><span id="power-count" class="power-count">0 / 3</span></div><div class="power-meter"><i id="power-meter-fill"></i></div><div id="circuit-slots" class="circuit-slots"></div><div class="fuse-instruction">ТВОИ ПРЕДОХРАНИТЕЛИ <span>каждый используется один раз</span></div><div id="fuse-tray" class="fuse-tray"></div></div><div id="fuse-feedback" class="fuse-feedback" aria-live="polite">🤖 Выбери любой предохранитель снизу.</div><div class="controls"><button class="secondary" onclick="fuseHint()">💡 Подсказка бота</button><button class="secondary" onclick="fuseReset()">Начать заново</button></div><div id="fuse-next"></div><details class="explain"><summary>Для защиты: где тут CSP?</summary>Нужно выбрать цвет предохранителя для каждого из трёх разъёмов. Ограничения: каждый разъём принимает только обозначенные цвета, каждый предохранитель используется один раз. Подсказка бота ищет допустимое распределение методом перебора с возвратом.</details></div>`);renderFuseGame()};
function renderFuseGame(){let count=Object.values(fuseState).filter(Boolean).length;let used=Object.values(fuseState);document.getElementById('power-count').textContent=`${count} / 3`;document.getElementById('power-meter-fill').style.width=`${count/3*100}%`;document.getElementById('circuit-slots').innerHTML=circuitData.map(c=>{let f=fuseData.find(x=>x.id===fuseState[c.id]);return `<button class="circuit-slot ${f?'powered '+f.className:''}" onclick="placeFuse('${c.id}')" aria-label="${c.title}: ${f?f.label:'пусто'}. Подходят ${c.allow.join(' и ')}"><span class="circuit-icon">${c.icon}</span><span class="circuit-label">${c.label}</span><strong>${c.title}</strong><span class="socket">${f?f.icon:'＋'}</span><span class="socket-text">${f?f.label+' · подключён':'ПУСТО'}</span><span class="accept">Подходят: ${c.allow.map(a=>`<i class="color-dot ${fuseData.find(x=>x.id===a).className}"></i>${fuseData.find(x=>x.id===a).label}`).join(' / ')}</span></button>`}).join('');document.getElementById('fuse-tray').innerHTML=fuseData.map(f=>`<button class="fuse-chip ${f.className} ${selectedFuse===f.id?'selected':''} ${used.includes(f.id)?'used':''}" onclick="selectFuse('${f.id}')" ${missionComplete?'disabled':''}><span class="chip-icon">${f.icon}</span><span><strong>${f.label}</strong><small>${used.includes(f.id)?'Уже подключён':selectedFuse===f.id?'Выбран':'Нажми, чтобы взять'}</small></span><span class="chip-arrow">↗</span></button>`).join('')}
function fuseFeedback(text,style=''){const el=document.getElementById('fuse-feedback');el.className='fuse-feedback '+style;el.textContent=text}
function selectFuse(id){if(missionComplete)return;if(Object.values(fuseState).includes(id)){fuseFeedback('Этот предохранитель уже подключён. Нажми на его разъём, чтобы снять.');return}if(selectedFuse===id){selectedFuse=null;renderFuseGame();fuseFeedback('Предохранитель возвращён. Выбери другой или нажми на подключённый разъём, чтобы снять его.');return}selectedFuse=id;renderFuseGame();fuseFeedback(`Выбран ${fuseData.find(f=>f.id===id).label.toLowerCase()} предохранитель. Теперь нажми на подходящий разъём.`)}
function placeFuse(id){if(missionComplete)return;let circuit=circuitData.find(c=>c.id===id);if(fuseState[id]&&!selectedFuse){let name=fuseData.find(f=>f.id===fuseState[id]).label;delete fuseState[id];renderFuseGame();fuseFeedback(`${name} предохранитель снят. Теперь можно подключить его заново.`);return}if(!selectedFuse){fuseFeedback('Сначала выбери предохранитель внизу.');return}if(fuseState[id]){fuseFeedback('Этот разъём уже занят. Сначала сними предохранитель: нажми на него без выбранного предмета.');return}if(!circuit.allow.includes(selectedFuse)){fuseFeedback('Не подходит! Посмотри на цвета под разъёмом и выбери один из них.','error');return}let name=fuseData.find(f=>f.id===selectedFuse).label;fuseState[id]=selectedFuse;selectedFuse=null;renderFuseGame();let count=Object.keys(fuseState).length;if(count===3){missionComplete=true;solved=true;renderFuseGame();fuseFeedback('⚡ Получилось! Свет включился, а дверь открыта.','success');document.getElementById('fuse-next').innerHTML='<button class="primary mission-next" onclick="show2()">ВЫБРАТЬСЯ ИЗ QAIRU ↗</button>';return}if(!cspCompletion(fuseState))fuseFeedback(`${name} подключён, но оставшиеся разъёмы нельзя заполнить. Сними один предохранитель и попробуй иначе.`, 'error');else fuseFeedback(`✓ ${name} подключён. Осталось включить ${3-count} из 3.`,'success')}
function fuseHint(){if(missionComplete)return;let result=cspCompletion(fuseState);if(!result){fuseFeedback('Текущая комбинация завела в тупик. Сними предохранитель из одного разъёма и попробуй ещё раз.','error');return}let target=circuitData.find(c=>!fuseState[c.id]);if(!target)return;let name=fuseData.find(f=>f.id===result[target.id]).label;fuseFeedback(`🤖 Подсказка: попробуй ${name.toLowerCase()} предохранитель для «${target.title}».`)}
function fuseReset(){fuseState={};selectedFuse=null;missionComplete=false;solved=false;document.getElementById('fuse-next').innerHTML='';renderFuseGame();fuseFeedback('🤖 Система сброшена. Выбери предохранитель снизу.')}
